static void Normalize(double[,] verts)
{
  for (int i = 0; i < verts.GetLength(0); i++)
  {
    double x = verts[i, 0];
    double y = verts[i, 1];
    double z = verts[i, 2];
    double len = Math.Sqrt(x * x + y * y + z * z);
    verts[i, 0] /= len;
    verts[i, 1] /= len;
    verts[i, 2] /= len;
  }
}

private IneqTree Balls()
{
  	var pol = Ineq3DOnline.PlatonicSolids.Polyhedron.CreateDodecahedron();

  	var res = pol.ToIneqTree();	


    foreach (var f in pol.Faces)
    {
      	double x = 0;
      	double y = 0;
      	double z = 0;
      
		foreach(var i in f)
        {
			x += pol.Vertices[i].X;
          	y += pol.Vertices[i].Y;
          	z += pol.Vertices[i].Z;
        }
      
      	x /= 5; y /= 5; z /= 5;
      	double len = Math.Sqrt(x * x + y * y + z * z);
      	x /= len; y /= len; z /= len;
      
		res = res & !Ball(x, y, z, 0.35);
    }
  
   	return res;
}

public IneqMesh GetIneqMesh()
{
    return new IneqMesh
    {
        X0 = -1.8,
        Y0 = -1.8,
        Z0 = -1.8,
        X1 = 1.8,
        Y1 = 1.8,
        Z1 = 1.8,
        D = 0.1d,
        Boxed = false,
        IneqTree = Balls() 
	};
}
